# Completa la línea marcada y compruébala con py check.
def publicos(activos):
    salida = []
    for a in activos:
        if a["en_alcance"]:
            salida.append(a["id"])   # ← cambia esta línea: solo si la exposición dice «público»
    return salida

print(publicos([{"id": "A-01", "en_alcance": True, "exposicion": "público en la web"},
                {"id": "A-02", "en_alcance": True, "exposicion": "interno"}]))   # ['A-01']
